# The outline every new document starts from until the organisation's administrator changes it:
# one section, no starting text, in Ukrainian, the language the platform ships for.
DEFAULT_OUTLINE = "# Загальні положення\n"


def seed(apps, schema_editor):
    """Every tenant schema starts with one type, the root folder and the template."""
    DocumentType = apps.get_model("documents", "DocumentType")
    Folder = apps.get_model("documents", "Folder")
    DocumentTemplate = apps.get_model("documents", "DocumentTemplate")
    DocumentType.objects.get_or_create(
        code="document", defaults={"label": "Документ", "actor_kind": "system"}
    )
    # The root's name is not stored: it is shown as the organisation's.
    Folder.objects.get_or_create(number=1, defaults={"name": "", "actor_kind": "system"})
    if not DocumentTemplate.objects.exists():
        DocumentTemplate.objects.create(
            outline=DEFAULT_OUTLINE, title_page=False, actor_kind="system"
        )


